"""Exact DR8 prepared-engine teardown and inspection; no reassembly approval."""
import json,hashlib,re,fitz
from pathlib import Path
B=Path(__file__).resolve().parent;R=B.parents[3];D=B/'2026-engine';D.mkdir(exist_ok=True)
row=next(r for r in json.loads((B/'source-index.json').read_text()) if r['target']['model_year']==2026);P=Path(row['local_pdf_path']);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();assert sha(P)==row['document_sha256'];book=fitz.open(P);U=row['source_url'];steps=[]
def st(i,title,t,p,rec=False):steps.append(dict(id=i,title=title,instruction=t,depends_on=[steps[-1]['id']] if steps else [],source_pdf_pages=sorted(set(p)),source_links=[U+'#page='+str(n) for n in sorted(set(p))],diagram_reference_required=True,record_required=rec,verification=['Record actual measurements, condition and disposition.' if rec else 'Confirm the action and component accounting.']))
st('entry','Confirm the prepared engine','Record the exact US 2026 YZ250F stock engine identity and completed engine-removal preparation. Engine must be cold, cleaned, drained and secured on a stable bench fixture; electrical/fuel/intake/exhaust/radiator connections and upper mounting brackets already detached. This route ends with disassembled inspected parts, not a running engine. Head-bolt lubricant disagreement must be resolved before later reassembly.',[219,226,61,229],True)
st('cover','Open the top end','Remove the cylinder-head breather hose and spark plug, then the two cover bolts and cylinder-head cover. Retain the top timing-chain guide separately; remove the old cover gasket. Protect the open engine from dirt and keep parts identified.',[219])
st('tdc','Record timing before removal','Remove the timing-mark and crankshaft-end access screws. Turn the crankshaft counterclockwise with a wrench until the rotor TDC mark aligns with the cover mark and both illustrated cam sprocket marks align with the head edge. Record the alignment. Do not force a binding engine.',[220,221],True)
st('cams-out','Remove tensioner and cams','Remove the tensioner cap bolt, tensioner and gasket. Loosen all eight cam-cap bolts evenly in a crisscross pattern from outside inward. Lift the two caps while retaining both clips and dowels. Secure the timing chain with wire so it cannot fall, then remove the exhaust and intake cams. Keep caps matched to their original head and positions.',[220,221,222])
st('cam-lobes','Measure the cam lobes','Inspect each cam lobe for blue discoloration, pitting and scratches. Measure the illustrated lobe height with a micrometer: intake service limit 32.130 mm, exhaust 33.460 mm. Record each value; damaged or undersize cams require replacement.',[222],True)
st('cam-journals','Measure journal clearance','Temporarily place each cam in its original head position. Lay Plastigauge on the illustrated journal, install original dowels and caps, and tighten cap bolts to 10 N·m in a crisscross pattern from inside outward; the illustrated bolts use engine oil on threads/contact surfaces. Do not rotate the cam during measurement. Remove caps evenly and measure the strip width. Record clearance against 0.028–0.062 mm. Remove all Plastigauge residue afterward.',[220,222,224],True)
st('cam-disposition','Resolve worn cam supports','For an out-of-range journal clearance, measure the cam journal diameter against 21.959–21.972 mm. An out-of-range journal requires a new cam; if the journal is within range but clearance failed, replace the cylinder head and its cam caps as a matched set. Save the actual measurements and replacement decision. Remove the temporary cam installation and retain the components separately.',[222,223],True)
st('timing-condition','Inspect chain, sprockets and tensioner','Check chain links for damage or stiffness: a failed chain requires chain and camshaft replacement as a set. More than one-quarter tooth wear on the illustrated cam sprocket also requires that matched replacement. Inspect tensioner for cracking/damage; with light finger pressure on its rod, wind it fully clockwise using a thin screwdriver, release and verify smooth extension. Replace a failed tensioner assembly. Record decompressor cam smooth movement and projecting lever pin.',[223],True)
st('head-out','Remove the cylinder head','Use the exact six-position removal diagram: loosen each head fastener half a turn per pass in the illustrated order until all are fully loose, then remove. Keep the long M9×145 mm bolt at position3 distinct from the three M9×135 mm bolts at positions4–6. Lift the head while retaining the timing chain; remove the old gasket and intake-side chain guide. Retain dowels and washers. Leave oil-passage plug and head studs installed.',[226,227,228])
st('head-check','Check the head and guide','Inspect the intake-side chain guide for damage/wear. Remove combustion-chamber carbon with a rounded scraper without scratching the plug bore or head. Clear coolant-passage deposits/rust. Record head damage and check warpage with straightedge and thickness gauge across the illustrated paths; limit 0.05 mm. Head replacement also requires new valves. A failed warpage check needs a separately reviewed resurfacing operation; do not count this inspection as machining.',[228],True)
st('cylinder-out','Lift the cylinder','Remove the cylinder retaining bolt, lift the cylinder while supporting the piston and secured chain, and remove the base gasket and two dowels. Keep the case opening protected. Do not remove the exhaust-side chain-guide stopper plate in this bounded operation.',[238])
st('piston-out','Remove piston and rings','Cover the crankcase opening before removing a piston-pin clip. Deburr the clip groove and pin-bore area as required; withdraw the pin without hammering. If still difficult, use piston-pin puller 90890-01304 / YU-01304. Remove the piston, then top ring and oil-ring components by opening the ring ends carefully and lifting the opposite side over the crown. Account for clips and protect the exposed connecting rod and crankcase.',[238,239])
st('bore','Measure the cylinder','Inspect cylinder and piston walls for vertical scratches. Measure side-to-side and front-to-back at all three illustrated bore heights, recording D1–D6 and their maximum C. Standard bore is 77.000–77.010 mm; wear limit 77.060 mm. Scratches require cylinder replacement with piston/rings as a set. An out-of-spec bore requires cylinder reboring or replacement plus new piston/rings; machining is outside this inspection route.',[239],True)
st('piston-fit','Measure piston and actual fit','Measure piston diameter at the illustrated point 4.0 mm above the skirt bottom: 76.955–76.970 mm. Calculate actual fit as maximum measured bore C minus measured piston diameter; specified clearance 0.030–0.055 mm. Record both dimensions and the subtraction. An out-of-range piston diameter or clearance requires cylinder, piston and rings replaced as a set.',[239,240],True)
st('ring-check','Measure ring clearances','Clean carbon from rings and grooves before checking side clearance: standard 0.030–0.065 mm, service limit 0.115 mm. An out-of-spec side clearance requires piston/rings as a set. Square the top ring near the cylinder bottom with the piston crown as shown and record end gap; limit 0.50 mm. Replace a failed ring. The oil-ring expander gap is not measurable. Excessive oil-rail gap requires replacement of the complete oil-ring set. The cited section gives no numerical rail-gap tolerance, so do not invent a rail reuse limit.',[240],True)
st('pin-check','Inspect piston pin and bore','Record pin discoloration or grooves; a damaged pin requires replacement and a lubrication-system investigation. Measure pin OD (minimum 15.971 mm) and piston pin bore ID (maximum16.043 mm); replace the failed pin or piston respectively. Record actual bore-minus-pin fit against 0.002–0.022 mm; an unresolved fit is not accepted for assembly.',[52,240,241],True)
st('lifters','Identify lifters and pads','On the detached head, protect the timing-chain opening with a clean cloth and remove all four lifters and pads. Label their original locations individually and keep them separated. Inspect lifters for damage/scratches: failed lifters require lifter and cylinder-head replacement. Account for all pads before moving the head.',[231,232,236],True)
st('sealing','Check valve sealing before dismantling','With the valves still held by their springs, add clean solvent to intake and exhaust ports as illustrated and observe each seat for leakage. Record the result for all four valves. Leakage requires face, seat and contact-width inspection. Drain and dry the solvent before subsequent work; do not leave solvent in the parts.',[232],True)
st('valves-out','Remove valve assemblies','Use valve spring compressor90890-04200 / YM-04019 with attachment90890-04108 / YM-04108 (22 mm) to compress each spring and remove both cotters. Release the compressor in a controlled manner, then remove retainer, spring, valve, stem seal and spring seat. Keep every part assigned to its original valve position. Every removed valve requires a new stem seal for eventual assembly.',[231,232,234])
st('stem-guide','Measure stems and guides','Measure each valve stem and guide bore. Intake stem minimum4.945 mm; exhaust minimum4.430 mm. Guide IDs: intake5.000–5.012 mm, exhaust4.500–4.512 mm. Compute guide ID minus stem OD for each pair; maximum clearance intake0.080 mm, exhaust0.100 mm. Record each component dimension and actual clearance, not just pass/fail. Failed clearance requires guide replacement; new valve installation also requires a new guide. Guide renewal and subsequent seat refacing are separate repair work.',[52,233,234],True)
st('valve-runout','Inspect valve condition and runout','Clean carbon from face and seat for inspection. Record pitting/wear, mushroomed stem end and measured stem runout against0.020 mm. A mushroomed end or failed runout requires replacement. Do not grind or lap a valve and then return it to service: these are titanium intake and exhaust valves, and any valve used for seat lapping must be discarded in favor of a distinct new running valve.',[234,235],True)
st('seat-contact','Measure seat contact','Inspect each seat for pitting/wear. Apply blue layout fluid to its corresponding valve face, insert through the guide and press onto the seat to make an impression; measure the removed-blueing band at the illustrated contact location. Maximum width1.6 mm for both intake and exhaust. Record each result. Failed seat condition or contact width requires cylinder-head replacement under the inspection criteria; no seat machining or lapping is performed here. Clean layout fluid away afterward.',[234,235],True)
st('springs','Measure valve springs','Measure each spring free length. Intake minimum34.94 mm; exhaust minimum33.82 mm. Record all four readings and identify springs requiring replacement.',[235,236],True)
st('handoff','Save the inspection and repair plan','Account for every clip, cotter, dowel, pad, fastener and protective cloth. Keep reusable parts identified by original location, separate failed parts, and protect the open crankcase from debris. Save all measured values and matched replacement requirements. Engine remains disassembled. Resolve the documented head-bolt lubricant discrepancy and complete the required repair, assembly, timing, valve-clearance and commissioning procedures before any start.',[61,220,229,231,234,238],True)
pages=sorted({1,4}|{p for s in steps for p in s['source_pdf_pages']});labels=[]
for n in pages:
 found=[(z[1],m[0]) for z in book[n-1].get_text('blocks') for m in [re.findall(r'(?m)^\d+-\d+$',z[4])] if m];labels.append(f'{n}: '+(max(found)[1] if found else 'front matter'))
d=dict(schema_version=1,id='yamaha-2026-yz250f-top-end-teardown-inspection-v1',title='Disassemble and measure the prepared top end',target=row['target'],scope_confirmed=True,status='SOURCE_REVIEW_CANDIDATE',publication_status='PENDING_INDEPENDENT_REVIEW',component='engine',affected_components=['engine','cams','piston'],applicability={'included':'Exact US2026 standard YZ250F stock top end on a prepared removed engine.','excluded':['Assembled-bike engine removal/refit','Cylinder/head/seat machining or guide replacement','Piston/cylinder/head/valve reassembly, timing closure, valve adjustment, startup','Bottom-end rebuilding and oil-ring rail reuse approval'],'year_inheritance':'NONE'},entry_state=['Cold, cleaned, drained engine secured on a bench, all external top-end connections and upper brackets detached.','Cam cover, cams, head, cylinder, piston and valve assemblies still installed.'],exit_state=['Top end disassembled; actual inspection measurements, original component positions and repair dispositions saved.','Open engine protected; assembly and startup remain pending.'],preflight=['This is a teardown/inspection route. Arrange subsequent exact repair and reassembly before opening the engine.','Head-bolt preparation remains conflicted: PDF61 says molybdenum disulfide oil, PDF59 and dedicated229 specify molybdenum disulfide grease. No choice is made here.','Engine removal, draining and external access are prerequisites, not claimed as completed by this guide.'],critical_stop_conditions=['Engine not securely supported, residual fuel/coolant or incomplete external access','Binding during crank rotation, lost hardware or unaccounted debris','No exact repair/assembly plan or unresolved head-bolt lubricant requirement'],required_tools=[{'name':x} for x in ['Stable engine bench fixture and labeled component trays','Suitable sockets and 10 N·m torque tool','Micrometers, bore gauges, straightedge, feeler gauges, dial gauge/V-blocks','Plastigauge and measuring scale','Thin screwdriver and wire to retain timing chain','Piston-pin puller90890-01304 / YU-01304 if needed','Valve spring compressor90890-04200 / YM-04019 and22mm attachment90890-04108 / YM-04108','Rounded carbon scraper, clean solvent and blue layout fluid']],required_parts=[{'name':'New gaskets, piston-pin clips and valve stem seals will be required for later assembly; determine additional replacement sets from actual inspection.'}],source={'source_url':U,'document_sha256':row['document_sha256'],'document_revision':row['document_revision'],'pdf_pages':pages,'printed_pages':labels,'review_status':'PENDING_INDEPENDENT_REVIEW','review_note':'Exact DR8 text and diagrams reviewed by author. Independent review pending; prepared-engine inspection scope only.'},steps=steps,operation_dependencies=[],completeness='Continuous prepared-engine top-end disassembly and measured inspection. Does not close repair, reassembly or return to running condition.')
out=D/'top-end-teardown-inspection-v1.procedure.json'
if out.exists():assert json.loads(out.read_text(encoding='utf8'))['publication_status']!='APPROVED'
def wr(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
wr(out,d);wr(D/'source-review-manifest.json',{'status':'PENDING_INDEPENDENT_REVIEW','sources':[{'id':'yamaha-us-2026-yz250f-oem','url':U,'sha256':row['document_sha256'],'local_pdf_path':str(P)}],'artifacts':[{'path':out.name,'kind':'procedure','sha256':sha(out),'source_id':'yamaha-us-2026-yz250f-oem','target':d['target'],'step_count':len(steps)}]});print(len(steps),sha(out))
